selector_to_html = {"a[href=\"#pyskyfire.common.friction.transition_weight\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.transition_weight\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">transition_weight</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re_critical</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the shared laminar-to-turbulent blending weight.</p><p>The weight is zero through <code class=\"docutils literal notranslate\"><span class=\"pre\">Re_critical</span></code> and one from\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Re_critical</span> <span class=\"pre\">*</span> <span class=\"pre\">(3500/2300)</span></code> onward. Between those limits it follows the\ncubic smoothstep <code class=\"docutils literal notranslate\"><span class=\"pre\">3*x**2</span> <span class=\"pre\">-</span> <span class=\"pre\">2*x**3</span></code>, giving continuous values and first\nderivatives where the pure laminar and turbulent branches are joined.</p><p>The fixed critical value <code class=\"docutils literal notranslate\"><span class=\"pre\">2040</span></code> is used for straight ducts. Curved ducts\nsupply Schmidt\u2019s geometry-dependent critical Reynolds number.</p></dd>", "a[href=\"#pyskyfire.common.friction.ReDh_turbulent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.ReDh_turbulent\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ReDh_turbulent</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">3500</span></span></dt><dd></dd>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">\u00b6</a></h2><p>Both curvature multipliers are helical-coil correlations. They model curvature\nas an enhanced local wall friction over a continuously curved duct, which fits\na cooling channel bending gently over many diameters. They are <em>not</em> a model\nfor a discrete pipe bend, where the loss is set by secondary-flow development\nand its decay downstream. Use a fitting loss coefficient for those.</p>", "a[href=\"#pyskyfire.common.friction.curvature_multiplier\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.curvature_multiplier\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">curvature_multiplier</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the friction multiplier due to streamwise curvature.</p><p class=\"rubric\">Notes</p><p>Limits are from the <code class=\"docutils literal notranslate\"><span class=\"pre\">fluids.friction</span></code> documentation for\n<code class=\"docutils literal notranslate\"><span class=\"pre\">helical_laminar_fd_Schmidt</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">helical_turbulent_fd_Schmidt</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">helical_transition_Re_Schmidt</span></code>. These warnings concern the coil models,\nnot straight-pipe Colebrook numerical accuracy or two-phase validity.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#exceptions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Exceptions<a class=\"headerlink\" href=\"#exceptions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.common.friction\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.friction<a class=\"headerlink\" href=\"#module-pyskyfire.common.friction\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct friction physics shared by cooling channels and piping.</p><p>This module is deliberately geometry-agnostic. Every entry point takes plain\nscalars \u2013 a Reynolds number, a hydraulic diameter, an absolute roughness, a\nsigned radius of curvature \u2013 so the same physics serves a regen cooling\nchannel marching on an axial coordinate and a pipe run marching on arc length.\nAnything that knows about contours, centerlines or stations belongs elsewhere.</p>", "a[href=\"FrictionCorrelationWarning.html#pyskyfire.common.friction.FrictionCorrelationWarning\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.FrictionCorrelationWarning\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">exception</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FrictionCorrelationWarning</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/builtins/exceptions.html#UserWarning\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">UserWarning</span></code></a></p><p>A friction correlation is being extrapolated beyond a documented limit.</p></dd>", "a[href=\"#pyskyfire.common.friction.friction_pressure_gradient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.friction_pressure_gradient\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">friction_pressure_gradient</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">velocity</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">np.inf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">curvature_correction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the irreversible pressure gradient <code class=\"docutils literal notranslate\"><span class=\"pre\">dp/ds</span></code> [Pa m\u207b\u00b9].</p><p>This is the friction term of the one-dimensional momentum equation only.\nThe reversible acceleration term <code class=\"docutils literal notranslate\"><span class=\"pre\">-rho</span> <span class=\"pre\">u</span> <span class=\"pre\">du/ds</span></code> depends on the state at\nboth ends of a segment rather than on a local gradient, so the caller\napplies it while marching.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.friction.annulus_laminar_factor\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.annulus_laminar_factor\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">annulus_laminar_factor</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius_ratio</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return a concentric annulus\u2019 laminar <code class=\"docutils literal notranslate\"><span class=\"pre\">f*Re</span></code> relative to a pipe\u2019s 64.</p><p>The exact fully developed solution on the hydraulic diameter\n<code class=\"docutils literal notranslate\"><span class=\"pre\">2*(r_o</span> <span class=\"pre\">-</span> <span class=\"pre\">r_i)</span></code> is <code class=\"docutils literal notranslate\"><span class=\"pre\">f*Re</span> <span class=\"pre\">=</span> <span class=\"pre\">64*(1-k)**2</span> <span class=\"pre\">/</span> <span class=\"pre\">(1</span> <span class=\"pre\">+</span> <span class=\"pre\">k**2</span> <span class=\"pre\">+</span> <span class=\"pre\">(1-k**2)/ln</span> <span class=\"pre\">k)</span></code>\nwith <code class=\"docutils literal notranslate\"><span class=\"pre\">k</span> <span class=\"pre\">=</span> <span class=\"pre\">r_i/r_o</span></code>. It runs from 1 for a pipe (<code class=\"docutils literal notranslate\"><span class=\"pre\">k</span> <span class=\"pre\">=</span> <span class=\"pre\">0</span></code>) to 1.5 for\nparallel plates (<code class=\"docutils literal notranslate\"><span class=\"pre\">k</span> <span class=\"pre\">-&gt;</span> <span class=\"pre\">1</span></code>). Turbulent friction on the same hydraulic\ndiameter differs from a pipe\u2019s by only a few percent and is not corrected.</p></dd>", "a[href=\"#pyskyfire.common.friction.ReDh_laminar\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.ReDh_laminar\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ReDh_laminar</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">2300</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.friction.FRICTION_MODELS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.FRICTION_MODELS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FRICTION_MODELS</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">('native',</span> <span class=\"pre\">'fluids')</span></span></dt><dd></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.friction.darcy_friction_factor\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.darcy_friction_factor\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">darcy_friction_factor</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">laminar_factor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the Darcy friction factor for a straight duct.</p></dd>", "a[href=\"#pyskyfire.common.friction.resolve_friction_model\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.resolve_friction_model\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">resolve_friction_model</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">model</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return a validated backend name.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
